    source: "BBC World",
    url: "https://www.bbc.co.uk/news/articles/c75gvzxrz49o?at_medium=RSS&at_campaign=rss",
    time: "3 ore fa",
    pub_ts: 1785938649,
    published_at: "2026-08-05T14:04:09+00:00",
    language: "en",
    score: 1,
